#define add(p) o = max(o, smoothstep(9. / r.y, .0, length(p) - .02))
#define H(p) fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453)  // hash
#define rot(a) mat2(cos(a + vec4(0, 1, 3, 0) * pi / 2.))
#define pi acos(-1.)
#define tau (2. * pi)
#define sq sqrt(3.)
#define hex vec2(1, sq)

void hexgrid(vec2 u, out vec2 p, out vec2 id) {
    vec2 a = mod(u,            hex) - hex / 2.,
         b = mod(u - hex / 2., hex) - hex / 2.;

    p = a;
    id = floor(u / hex) * 2.;

    if(dot(a, a) > dot(b, b)) {
        id = floor(u / hex - .5) * 2. + 1.;
        p = b;
    }
}


vec2 coord(vec2 p, float r, float n, float dir){
    p = vec2(
            atan(p.y, p.x) + dir * iTime,
            length(p)
        );

    float d = mod(p.x * n, tau) - pi;
          d /=  n;

    return p.y * cos(d + vec2(0, 3) * pi / 2.) - vec2(.288, 0) * r;
}


vec4 sino(vec4 o, vec2 p, float r) {
    vec2 q = p *= rot(r * pi / 3.);

    float k = 8., 
          dx = iTime * 3. / 2. / tau,
          d = floor((p.x - dx) * k) / k,
          dy = smoothstep(1., 0., abs(d + dx + .5 / k) * 2.);

    q = vec2(
            mod(q.x - dx, 1. / k) - .5 / k,
            q.y - dy * .2
        );

    return max(o, smoothstep(9. / iResolution.y, .0, length(q) - .02));
}

void mainImage(out vec4 o, vec2 u) {
    vec2 r = iResolution.xy, q, p, id;
    u = (u + u - r) / r.y 
            * (2.5 + tanh(cos(iTime * .3) * 6. - 4.) * 1.5)
        + tanh(cos(vec2(iTime * 2./13., iTime * 3./13. + 33.)) * 4.) * 5.;
    o *= .0;

    hexgrid(u, p, id);

    int k = int(id.x);
    float dir = k % 3 == 1 ? -1. : 1.;

    o.rg += float(k % 3) * .1 + .2;

    //if(false) // stop rotate
    p *= rot(
             tanh(
                 cos(iTime * .1 + H(id) * pi)
                     * 18.
             )
                 * floor(H(id + .1) * 3.) * tau / 3.   
         );

    if(false) // static rotate
    p *= rot(floor(H(id + .1) * 3.) * tau / 3.);
    int dice = int(H(id + .3) * 3.);

    //dice = 2;

    if(dice == 0){ // sanduich
        p.y *= H(id + .2) > .5 ? -1. : 1. ;
        add(coord(p + dir * vec2(.5, .288), 1., 12., dir));
        add(coord(p - dir * vec2(.5, .288), 1., 12., -dir));

        q = p * rot(4. * pi / 3.);
        q.x = mod(q.x - iTime * 3. / 2. / tau, 1. / 8.) - 1. / 16.;
        add(q);
    }

    if(dice == 1){ // trefoil
        p.y *= H(id + .2) > .5 ? -1. : 1. ;
        add(coord(p + dir * vec2(.5, .288), 1., 12., dir));
        add(coord(p + dir * vec2(-.5, .288), 1., 12., dir));
        add(coord(p + dir * vec2(0, -.577), 1., 12., dir));
    }

    if(dice == 2){ // flux capacitor
        o = sino(o, p, 0.);
        o = sino(o, p, 2.);
        o = sino(o, p, 4.);
    }
}
